package com.bank.explain.plan;

public class PlanNode {
    private final String nodeType;   // "Seq Scan" or "Index Scan"
    private final long estRows;
    private final double estCost;
    private long actualRows = -1;     // filled by EXPLAIN ANALYZE
    private double actualMs = -1;

    public PlanNode(String nodeType, long estRows, double estCost) {
        this.nodeType = nodeType; this.estRows = estRows; this.estCost = estCost;
    }
    public void recordActual(long rows, double ms) { this.actualRows = rows; this.actualMs = ms; }

    public String getNodeType() { return nodeType; }
    public long getEstRows() { return estRows; }
    public double getEstCost() { return estCost; }
    public long getActualRows() { return actualRows; }
    public double getActualMs() { return actualMs; }
}
