package com.bank.explain.plan;

// Chooses Seq Scan vs Index Scan like a tiny optimizer.
public class MiniPlanner {
    private final long tableRows;
    private final int indexDepth;

    public MiniPlanner(long tableRows, int indexDepth) { this.tableRows = tableRows; this.indexDepth = indexDepth; }

    // sargable=true and indexExists=true → Index Scan; otherwise Seq Scan.
    public PlanNode plan(boolean indexExists, boolean sargable, long matchingRows) {
        if (indexExists && sargable) {
            double cost = matchingRows * indexDepth;             // cheap, proportional to matches
            return new PlanNode("Index Scan", matchingRows, cost);
        }
        double cost = tableRows;                                  // Seq Scan reads everything
        return new PlanNode("Seq Scan", matchingRows, cost);
    }
}
