package com.bank.explain.service;

import com.bank.explain.plan.*;
import java.util.logging.*;

public class ExplainService {
    private static final Logger log = Logger.getLogger(ExplainService.class.getName());

    public void explain(String label, PlanNode node) {
        log.info(() -> "EXPLAIN " + label + ": " + node.getNodeType()
                + " (est rows=" + node.getEstRows() + " cost=" + node.getEstCost() + ")");
        if (node.getNodeType().equals("Seq Scan"))
            log.warning(() -> "RED FLAG: Seq Scan on a large table for " + label);
    }

    public void explainAnalyze(String label, PlanNode node, long actualRows, double actualMs) {
        node.recordActual(actualRows, actualMs);
        log.info(() -> "EXPLAIN ANALYZE " + label + ": " + node.getNodeType()
                + " est=" + node.getEstRows() + " actual=" + node.getActualRows()
                + " time=" + node.getActualMs() + "ms");
        if (node.getActualRows() > node.getEstRows() * 100L)
            log.warning(() -> "Estimate vs actual gap huge for " + label + " → run ANALYZE (stale stats)");
    }
}
