package com.bank.explain;

import com.bank.explain.plan.*;
import com.bank.explain.service.ExplainService;
import java.util.logging.*;

public class ExplainDemo {
    private static final Logger log = Logger.getLogger(ExplainDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        MiniPlanner planner = new MiniPlanner(200_000_000L, 4);
        ExplainService explain = new ExplainService();

        // Query 1: sargable, index exists → Index Scan
        PlanNode good = planner.plan(true, true, 500);
        explain.explain("WHERE account_id='SAV2001'", good);
        explain.explainAnalyze("WHERE account_id='SAV2001'", good, 500, 1.2);

        // Query 2: non-sargable (UPPER on column) → Seq Scan despite index
        PlanNode bad = planner.plan(true, false, 500);
        explain.explain("WHERE UPPER(account_id)='SAV2001'", bad);
        explain.explainAnalyze("WHERE UPPER(account_id)='SAV2001'", bad, 500, 4200.0);

        // Query 3: stale statistics → estimate far below actual
        PlanNode stale = new PlanNode("Index Scan", 10, 40);
        explain.explainAnalyze("WHERE amount>1,00,000", stale, 5_000_000, 9000.0);
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

